def __init__(self, filepath_or_buffer, index=None, encoding="ISO-8859-1", chunksize=None):
    self._encoding = encoding
    self._lines_read = 0
    self._index = index
    self._chunksize = chunksize

    # Check if the input is a string or a bytes-like object or a file-like object
    if isinstance(filepath_or_buffer, str):
        filepath_or_buffer, encoding, compression, should_close = get_filepath_or_buffer(filepath_or_buffer, encoding=encoding)
        self.filepath_or_buffer = open(filepath_or_buffer, "rb")
    elif isinstance(filepath_or_buffer, (bytes, BytesIO)):
        # If it's bytes or a BytesIO object, directly use it
        if isinstance(filepath_or_buffer, bytes):
            self.filepath_or_buffer = BytesIO(filepath_or_buffer)
        else:
            self.filepath_or_buffer = filepath_or_buffer
    elif hasattr(filepath_or_buffer, 'read') and callable(filepath_or_buffer.read):
        # If it's a file-like object, use it directly
        self.filepath_or_buffer = filepath_or_buffer
    else:
        raise ValueError("Invalid input type for filepath_or_buffer. Must be str, bytes, or a file-like object.")

    # Now we can read the contents if needed
    if isinstance(self.filepath_or_buffer, BytesIO):
        contents = self.filepath_or_buffer.getvalue()
        try:
            contents = contents.decode(self._encoding)
        except (UnicodeEncodeError, AttributeError):
            pass  # If it's bytes, do nothing
    else:
        # Ensure the file-like object is opened ready for reading
        contents = self.filepath_or_buffer.read()

    self._read_header()
