def __init__(
    self, filepath_or_buffer, index=None, encoding="ISO-8859-1", chunksize=None
):

    self._encoding = encoding
    self._lines_read = 0
    self._index = index
    self._chunksize = chunksize

    if isinstance(filepath_or_buffer, str):
        (
            filepath_or_buffer,
            encoding,
            compression,
            should_close,
        ) = get_filepath_or_buffer(filepath_or_buffer, encoding=encoding)

    if isinstance(filepath_or_buffer, (str, bytes)):
        self.filepath_or_buffer = open(filepath_or_buffer, "rb")
    elif hasattr(filepath_or_buffer, 'read'):  # Check if it's a file-like object
        self.filepath_or_buffer = filepath_or_buffer
    else:
        raise ValueError("Invalid file path or buffer object type: {}".format(type(filepath_or_buffer)))

    if hasattr(self.filepath_or_buffer, 'read'):
        contents = self.filepath_or_buffer.read()
        if isinstance(contents, str):
            try:
                contents = contents.encode(self._encoding)
            except UnicodeEncodeError:
                raise ValueError("Encoding failed due to incompatible characters in the data.")
        self.filepath_or_buffer = BytesIO(contents)

    self._read_header()
