```python
def __init__(self, filepath_or_buffer, index=None, encoding="ISO-8859-1", chunksize=None):
    self._encoding = encoding
    self._lines_read = 0
    self._index = index
    self._chunksize = chunksize

    if isinstance(filepath_or_buffer, str):
        filepath_or_buffer, encoding, compression, should_close = get_filepath_or_buffer(filepath_or_buffer, encoding=encoding)
    elif not hasattr(filepath_or_buffer, 'read'):
        raise ValueError("filepath_or_buffer must be a string, bytes, or a file-like object.")

    if isinstance(filepath_or_buffer, (str, bytes)):
        self.filepath_or_buffer = open(filepath_or_buffer, "rb")
    else:
        # For file-like objects, no encoding should be applied
        contents = filepath_or_buffer.read()
        if not isinstance(contents, bytes):
            raise ValueError("Expected bytes-like object from filepath_or_buffer.")
        self.filepath_or_buffer = BytesIO(contents)

    self._read_header()
